#pragma once
#include "geo_selftest.h"
static GeoArea stagedArea;static int stagedId=-1;static bool stagedActions[2]{false,false};static uint32_t stageUntil=0;
static const char* geoMotionNames[]={"DRIVING","STOPPED","NO_FIX"};static const char* geoModeNames[]={"LOAD","DRIVE","WORK","OFF","INHERIT"};
static String hexColor(uint32_t color){char h[7];snprintf(h,sizeof(h),"%06lX",(unsigned long)color);return String(h);}
static bool geoNumber(const String& s,double low,double high,double& value){char*end=nullptr;value=strtod(s.c_str(),&end);return s.length()&&end&&*end==0&&isfinite(value)&&value>=low&&value<=high;}
static bool geoInt(const String& s,int low,int high,int& out){double n;if(!geoNumber(s,low,high,n)||floor(n)!=n)return false;out=(int)n;return true;}
static bool geoHex(const String& s,uint32_t& value){if(s.length()!=6)return false;for(unsigned i=0;i<s.length();i++)if(!isxdigit((unsigned char)s[i]))return false;value=strtoul(s.c_str(),nullptr,16);return true;}
static int geoFields(const String& c){int count=0;for(unsigned i=0;i<c.length();i++)if(c[i]=='|')count++;return count;}
static int geoMotionIndex(const String& s){for(int i=0;i<3;i++)if(s==geoMotionNames[i])return i;return -1;}
static bool geoParseAction(const String& c,int start,GeoAction& a){int mode,pattern,brightness;if(!geoInt(tok(c,start),0,4,mode)||!geoInt(tok(c,start+1),0,11,pattern)||!geoHex(tok(c,start+2),a.primary)||!geoHex(tok(c,start+3),a.secondary)||!geoInt(tok(c,start+4),1,255,brightness))return false;a.mode=mode;a.pattern=pattern;a.brightness=brightness;return geoActionValid(a);}
static String geoActionText(const GeoAction& a){return String(a.mode)+"|"+String(a.pattern)+"|"+hexColor(a.primary)+"|"+hexColor(a.secondary)+"|"+String(a.brightness);}
static void sendGround(){ble.notify("GROUND_CONFIG|"+String(geo.spacingMm)+"|"+String(geo.widthMm)+"|"+String(geo.reverse[0])+"|"+String(geo.reverse[1])+"|"+String(geo.offsetMm[0])+"|"+String(geo.offsetMm[1]));}
static void sendGeoSettings(){ble.notify("GEO_CONFIG|"+String(geo.enabled)+"|"+String(geo.manualOverride)+"|"+String(geo.dwellMs)+"|"+String(geo.marginM)+"|"+String(geo.stoppedMph,1)+"|"+String(geo.drivingMph,1)+"|12|12");for(int i=0;i<3;i++)ble.notify("GEO_FALLBACK|"+String(geoMotionNames[i])+"|"+geoActionText(geo.fallback[i]));}
static void sendGeoState(){String control=!geo.enabled?"OFF":geo.manualOverride?"PAUSED":"AUTO";String source=geoResult.id>=0?String(geo.areas[geoResult.id].name):geoResult.motion==GEO_NO_FIX?String("No fresh GPS"):String("Outside saved areas");ble.notify("GEO_STATE|"+control+"|"+String(geoResult.id)+"|"+source+"|"+geoMotionNames[geoResult.motion]+"|"+geoActionText(geoResult.action)+"|"+String(geoResult.active)+"|"+String(geoResult.pending));}
static void sendGeoList(){ble.notify("GEO_LIST_BEGIN");for(int i=0;i<GEO_MAX_AREAS;i++){auto&a=geo.areas[i];if(!a.used)continue;ble.notify("GEO_AREA|"+String(i)+"|"+a.name+"|"+String(a.priority)+"|"+String(a.enabled)+"|"+(a.shape?"P":"C")+"|"+String(a.radius)+"|"+String(a.count));for(int j=0;j<a.count;j++)ble.notify("GEO_VERTEX|"+String(i)+"|"+String(a.points[j].lat*1e-7,7)+"|"+String(a.points[j].lon*1e-7,7));for(int j=0;j<2;j++)ble.notify("GEO_AREA_ACTION|"+String(i)+"|"+geoMotionNames[j]+"|"+geoActionText(a.action[j]));}ble.notify("GEO_LIST_END");}
static bool applyGeoConfig(const GeoConfig& next){if(!geoConfigValid(next)){ble.notify("ERR|BAD_GEO_CONFIG");return false;}if(!saveGeo(next)){ble.notify("ERR|GEO_SAVE_FAILED");return false;}geo=next;geoEngine.reset();leds.setGround(geo,strips);return true;}
static void pauseGeo(){if(geo.enabled&&!geo.manualOverride){geo.manualOverride=1;if(!saveGeo(geo))ble.notify("WARN|GEO_PAUSE_NOT_PERSISTED");sendGeoSettings();}}
static bool geoCommand(const String& c){String op=tok(c,0);op.toUpperCase();
 if(op=="RUN_AUTO_TESTS"){int count=0;bool ok=geoSelfTest(count);ble.notify("AUTO_TESTS|"+String(ok?"PASS":"FAIL")+"|"+String(count));return true;}
 if(op=="GET_GEO_CONFIG"){sendGeoSettings();sendGround();sendGeoState();return true;}
 if(op=="GET_GEO_AREAS"){sendGeoList();return true;}
 if(op=="GET_GROUND_CONFIG"){sendGround();return true;}
 if(op=="GET_GEO_STATE"){sendGeoState();return true;}
 if(op=="GEO_CANCEL"){stagedId=-1;ble.notify("OK|GEO_CANCEL");return true;}
 if(op=="GEO_CONTROL"){String x=tok(c,1);if(geoFields(c)!=1||(x!="AUTO"&&x!="PAUSE"&&x!="OFF")){ble.notify("ERR|BAD_MODE");return true;}GeoConfig next=geo;next.enabled=x!="OFF";next.manualOverride=x=="PAUSE";if(applyGeoConfig(next)){ble.notify("OK|GEO_CONTROL");sendGeoSettings();sendGeoState();}return true;}
 if(op=="SET_GEO_SETTINGS"){int dwell,margin;double stop,drive;if(geoFields(c)!=4||!geoInt(tok(c,1),0,10000,dwell)||!geoInt(tok(c,2),0,50,margin)||!geoNumber(tok(c,3),0,20,stop)||!geoNumber(tok(c,4),.1,30,drive)||drive<=stop){ble.notify("ERR|BAD_GEO_SETTINGS");return true;}GeoConfig next=geo;next.dwellMs=dwell;next.marginM=margin;next.stoppedMph=stop;next.drivingMph=drive;if(applyGeoConfig(next)){ble.notify("OK|SET_GEO_SETTINGS");sendGeoSettings();}return true;}
 if(op=="SET_GEO_FALLBACK"){int state=geoMotionIndex(tok(c,1));GeoAction a;if(geoFields(c)!=6||state<0||!geoParseAction(c,2,a)){ble.notify("ERR|BAD_GEO_ACTION");return true;}GeoConfig next=geo;next.fallback[state]=a;if(applyGeoConfig(next)){ble.notify("OK|SET_GEO_FALLBACK");sendGeoSettings();}return true;}
 if(op=="SET_GROUND_CONFIG"){int values[6];int low[]={100,20,0,0,-10000,-10000},high[]={10000,10000,1,1,10000,10000};bool valid=geoFields(c)==6;for(int i=0;i<6;i++)if(!geoInt(tok(c,i+1),low[i],high[i],values[i]))valid=false;if(!valid||values[1]>values[0]){ble.notify("ERR|BAD_GROUND_CONFIG");return true;}GeoConfig next=geo;next.spacingMm=values[0];next.widthMm=values[1];for(int i=0;i<2;i++){next.reverse[i]=values[i+2];next.offsetMm[i]=values[i+4];}if(applyGeoConfig(next)){ble.notify("OK|SET_GROUND_CONFIG");sendGround();}return true;}
 if(op=="GEO_BEGIN"){int id,priority,enabled,radius;String name=tok(c,2),shape=tok(c,5);if(geoFields(c)!=6||!geoInt(tok(c,1),0,11,id)||name.length()<1||name.length()>24||!geoInt(tok(c,3),0,100,priority)||!geoInt(tok(c,4),0,1,enabled)||(shape!="C"&&shape!="P")||!geoInt(tok(c,6),5,5000,radius)){ble.notify("ERR|BAD_GEO_AREA");return true;}stagedArea=GeoArea{};stagedArea.used=1;stagedArea.enabled=enabled;stagedArea.priority=priority;stagedArea.radius=radius;stagedArea.shape=shape=="P";name.toCharArray(stagedArea.name,sizeof(stagedArea.name));stagedId=id;stagedActions[0]=stagedActions[1]=false;stageUntil=millis()+60000;ble.notify("OK|GEO_BEGIN");return true;}
 if(op=="GEO_POINT"||op=="GEO_ACTION"||op=="GEO_COMMIT"){if(stagedId<0||(int32_t)(millis()-stageUntil)>=0){stagedId=-1;ble.notify("ERR|GEO_STAGE_EXPIRED");return true;}stageUntil=millis()+60000;
  if(op=="GEO_POINT"){double lat,lon;if(geoFields(c)!=2||stagedArea.count>=GEO_MAX_POINTS||(!stagedArea.shape&&stagedArea.count)||!geoNumber(tok(c,1),-85,85,lat)||!geoNumber(tok(c,2),-180,180,lon)){ble.notify("ERR|BAD_GEO_POINT");return true;}stagedArea.points[stagedArea.count++]={(int32_t)llround(lat*1e7),(int32_t)llround(lon*1e7)};ble.notify("OK|GEO_POINT");return true;}
  if(op=="GEO_ACTION"){int state=geoMotionIndex(tok(c,1));GeoAction a;if(geoFields(c)!=6||state<0||state>1||!geoParseAction(c,2,a)){ble.notify("ERR|BAD_GEO_ACTION");return true;}stagedArea.action[state]=a;stagedActions[state]=true;ble.notify("OK|GEO_ACTION");return true;}
  if(geoFields(c)!=0||!stagedActions[0]||!stagedActions[1]||!geoAreaValid(stagedArea)){ble.notify("ERR|BAD_GEO_AREA");return true;}GeoConfig next=geo;next.areas[stagedId]=stagedArea;if(applyGeoConfig(next)){stagedId=-1;ble.notify("OK|GEO_COMMIT");sendGeoList();}return true;
 }
 if(op=="GEO_DELETE"){int id;if(geoFields(c)!=1||!geoInt(tok(c,1),0,11,id)){ble.notify("ERR|BAD_GEO_ID");return true;}GeoConfig next=geo;next.areas[id]=GeoArea{};if(applyGeoConfig(next)){ble.notify("OK|GEO_DELETE");sendGeoList();}return true;}
 if(op=="GEO_EVALUATE"){double lat,lon;int motion;if(geoFields(c)!=3||!geoNumber(tok(c,1),-85,85,lat)||!geoNumber(tok(c,2),-180,180,lon)||!geoInt(tok(c,3),0,2,motion)){ble.notify("ERR|BAD_TEST_POINT");return true;}int id=GeoEngine::pick(geo,motion!=2,lat,lon,(GeoMotion)motion);GeoAction action=id>=0?geo.areas[id].action[motion]:geo.fallback[motion];ble.notify("GEO_RESULT|"+String(id)+"|"+geoActionText(action));return true;}
 return false;
}
